			}
			defer db.Close() //nolint:errcheck
			if err := db.UpdateTitle(cmd.Context(), sess.ID, args[1]); err != nil {
				return err
			}
			fmt.Printf("Updated title for %s\n", sess.ID)
			return nil
		},
	}
}

