)

const (
	StatusNeedsAttention = "needs_attention"
	StatusWorking        = "working"
	StatusIdle           = "idle"
	StatusDone           = "done"
	StatusStale          = "stale"
	StatusUnknown        = "unknown"
)

type Session struct {
	ID             string
	Source         string
	NativeID       string
	ProjectPath    string
	Agent          string
	Title          string
	TitleSource    string
	GoalSummary    string
